import json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; D=ROOT/'questions/science'
DATA=[
("直尺最小刻度為 1 mm，物體端點落在 12.3 cm 附近，合理的記錄方式是？",["約 12.3 cm，依估讀規則保留適當位數","只記 12 cm 並宣稱完全精確","記成 123 m","記成無限多位小數"],"A","最小刻度為 1 mm 時可估讀到適當的下一位，並依儀器能力記錄約 12.3 cm。","先看最小刻度，再決定可估讀的末位與單位。"),
("量筒讀取液面時，視線應如何放置以降低視差？",["與液面最低點同高並垂直讀取","從上方斜看","從下方仰看","閉眼估計"],"A","視線與液面最低點同高可避免視差造成的系統偏差；凹液面應讀最低點。","固定視線高度，再辨認凹液面讀值位置。"),
("游標卡尺的最小刻度比直尺細，主要優點是？",["可提供較高解析度與較小的估讀間距","可量測溫度","一定沒有任何誤差","可自動換算質量"],"A","刻度更細表示解析度較高，可讀出更細的長度差異，但仍需正確操作與校正。","把最小刻度連結到解析度，不把解析度等同零誤差。"),
("同一物體用同一把尺重複量測，讀值很接近但與標準值偏離，應優先檢查？",["零點或校正造成的系統誤差","再多量一次就必定消失的隨機誤差","物體立刻變形","單位名稱"],"A","結果集中但整體偏移，可能是零點未歸零或校正問題，需檢查儀器。","比較集中程度與偏離方向。"),
("要判讀指針落在兩個刻度之間，估讀位數應由什麼決定？",["儀器最小刻度與可合理判讀的分度","題目希望的答案長度","操作者喜歡的位數","物體顏色"],"A","估讀位數需符合刻度間距與儀器解析度，不能任意增加數字。","由工具刻度反推可報告的精度。"),
("測量紙張厚度時，量一張的差異小於尺的最小刻度，較好的方法是？",["量多張總厚度再除以張數","只用手感判斷","把厚度改量成溫度","不記張數"],"A","量多張可放大總厚度，再平均得到單張厚度，降低相對讀值誤差。","將小量測量轉成較大的可讀總量。"),
("若天平最小刻度為 0.01 g，記錄 4.236 g 是否合理？",["通常不合理，超出儀器可支持的位數","一定最精確","應改成 4.236 kg","與最小刻度無關"],"A","0.01 g 的解析度通常只能支持到小數第二位附近，4.236 g 多報了一位。","比較報告末位與儀器最小刻度。"),
("用溫度計量水溫時，感測端不應貼著容器底部，主要因為？",["容器壁或底部溫度可能不同，會造成局部偏差","可以讓溫度變成質量","水沒有溫度","可增加刻度"],"A","感測端貼壁可能量到容器局部溫度而非水體代表溫度，應放在適當位置並攪拌均勻。","辨認感測器位置造成的代表性與系統偏差。"),
("同一量測由三位同學各做多次，若結果分散程度小且平均相近，表示？",["重複性與精密度較好，但仍需檢查準確度","一定沒有系統誤差","代表物理量沒有單位","只表示其中一次正確"],"A","結果彼此接近表示精密度較好；是否接近真值仍需標準值或校正判斷。","分開精密度與準確度。"),
("若要比較兩支刻度不同的量筒，最公平的做法是？",["用相同液體與體積重複量測，記錄最小刻度與誤差範圍","只比較外觀大小","讓每支量不同液體","忽略刻度差異"],"A","相同條件下重複量測，並把最小刻度與變異納入，才能比較工具性能。","固定樣本與程序，再比較解析度、偏差與變異。"),
]
for i,(prompt,opts,ans,ex,strategy) in enumerate(DATA,1):
 p=D/f'question-science-content-ea-iv-3-{i}.json'; old=json.loads(p.read_text()); text=opts[ord(ans)-65]
 old.update({'prompt':prompt,'options':[{'id':chr(65+j),'text':x} for j,x in enumerate(opts)],'answer':{'value':ans,'explanation':ex+f' 正確答案為選項 {ans}：「{text}」。'},'solutionStrategy':strategy,'solutionSteps':['定位概念：圈出 Ea-Ⅳ-3 的最小刻度、估讀、視差、校正或重複量測。','整理證據：先確認工具解析度，再分辨報告位數、偏差與變異。',f'套用原理：{ex}',f'排除干擾：檢查讀值位置、有效位數與誤差類型，正確選項是「{text}」。',f'最後回查：答案「{text}」符合儀器能力，沒有宣稱測量完全無誤差。'],'reviewStatus':'draft','updatedAt':'2026-09-08'})
 p.write_text(json.dumps(old,ensure_ascii=False,indent=2)+'\n')
print(f'rewrote {len(DATA)} questions')
